mapper.select:
SELECT f.id, f.user_id, u.user_name, f.content, f.reply, f.status, f.create_time, f.reply_time
FROM feedback f LEFT JOIN user u ON u.id = f.user_id

    AND f.user_id = #{userId}
    AND u.user_name LIKE concat('%', #{userName}, '%')

        AND (f.content LIKE concat('%', #{keyword}, '%') OR f.reply LIKE concat('%', #{keyword}, '%'))

    AND f.status = #{status}
    AND f.create_time BETWEEN #{startTime} AND #{endTime}

ORDER BY f.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM feedback f LEFT JOIN user u ON u.id = f.user_id

    AND f.user_id = #{userId}
    AND u.user_name LIKE concat('%', #{userName}, '%')

        AND (f.content LIKE concat('%', #{keyword}, '%') OR f.reply LIKE concat('%', #{keyword}, '%'))

    AND f.status = #{status}
    AND f.create_time BETWEEN #{startTime} AND #{endTime}
